package org.iets3.core.expr.genjava.tests.rt.rt;

/*Generated by MPS */


/**
 * Adds the URL of the source test node to failures of generated tests, so JUnit reports link back to MPS.
 * Generated test methods wrap their body: try { ... } catch (Throwable t) { throw SourceNodeFailures.attach(t, url); }
 * Plain Java, no MPS dependency at test runtime. The URL is computed during generation.
 */
public class SourceNodeFailures {
  /**
   * Text every node URL contains; a message containing it already carries a node URL.
   */
  public static final String URL_MARKER = "/node?ref=";
  private static final String[] PASS_THROUGH_CLASSES = new String[]{"org.junit.internal.AssumptionViolatedException", "org.opentest4j.TestAbortedException"};

  /**
   * Returns the throwable to rethrow, with " [url]" appended to its message.
   * An AssertionError stays an AssertionError (JUnit failure), any other throwable becomes a
   * SourceNodeTestException (JUnit error) whose message starts with the original class name.
   * The original throwable is the cause and its stack trace is kept.
   * Returned unchanged: null url, messages that already contain a node URL, assumption violations
   * (skipped tests stay skipped) and VirtualMachineErrors.
   */
  public static Throwable attach(Throwable failure, String url) {
    if (failure == null || url == null || url.isEmpty() || isPassThrough(failure)) {
      return failure;
    }
    String message = failure.getMessage();
    if (message != null && message.contains(SourceNodeFailures.URL_MARKER)) {
      return failure;
    }
    if (failure instanceof InterruptedException) {
      Thread.currentThread().interrupt();
    }
    String suffix = "[" + url + "]";
    if (failure instanceof AssertionError) {
      AssertionError assertion = new AssertionError(((message == null ? suffix : message + " " + suffix)));
      assertion.initCause(failure);
      assertion.setStackTrace(failure.getStackTrace());
      return assertion;
    }
    String text = failure.getClass().getName() + ((message == null ? "" : ": " + message)) + " " + suffix;
    SourceNodeTestException error = new SourceNodeTestException(text, failure, url);
    error.setStackTrace(failure.getStackTrace());
    return error;
  }

  private static boolean isPassThrough(Throwable failure) {
    if (failure instanceof VirtualMachineError) {
      return true;
    }
    for (String name : SourceNodeFailures.PASS_THROUGH_CLASSES) {
      try {
        if (Class.forName(name, false, failure.getClass().getClassLoader()).isInstance(failure)) {
          return true;
        }
      } catch (ClassNotFoundException | LinkageError notOnClasspath) {
        // test framework not on the classpath, so the failure can't be one of its classes
      }
    }
    return false;
  }

}
